begin isolation level repeatable read read only;
select jsonb_build_object('columns',(select jsonb_agg(jsonb_build_object('table',table_schema||'.'||table_name,'name',column_name,'type',data_type) order by table_schema,table_name,ordinal_position) from information_schema.columns where (table_schema,table_name) in (('public','raw_payment_sms'),('public','parsed_payment_events'),('public','payments'),('public','provider_finality_requests'),('public','notification_deliveries'),('public','notification_delivery_attempts'),('public','notification_events'),('collect_hybrid','momo_journal_entries'),('collect_hybrid','momo_journal_lines'),('collect_hybrid','momo_reversal_requests'),('collect_hybrid','momo_reconciliation_exceptions'),('collect_hybrid','sms_notification_outbox'),('collect_hybrid','sms_notification_attempts'),('collect_security','reconciliation_reviews'))), 'functions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid)) order by p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','collect_admin_access') and p.proname in ('assert_admin_permission','collect_get_notification_health','admin_system_health')));rollback;